mapper.select:
SELECT legal_support_id, legal_support_name, SUM(performance_goal) as sum1, SUM(visit_goal) as sum2, SUM(achieved_performance_goal) as sum3, SUM(achieved_visit_goal) as sum4 FROM dc_performance_task WHERE 1=1
AND legal_support_id = #{legalSupportId}
AND task_month = #{taskMonth}
AND task_month = DATE_FORMAT(CURRENT_DATE(), '%Y%m')
GROUP BY legal_support_id, legal_support_name

SELECT legal_support_id, legal_support_name, SUM(performance_goal) as sum1, SUM(visit_goal) as sum2, SUM(achieved_performance_goal) as sum3, SUM(achieved_visit_goal) as sum4 FROM dc_performance_task WHERE 1=1
AND legal_support_id = #{legalSupportId}
AND YEAR(STR_TO_DATE(task_month, '%Y%m')) = #{taskYear}
AND YEAR(STR_TO_DATE(task_month, '%Y%m')) = YEAR(CURRENT_DATE())
GROUP BY legal_support_id, legal_support_name
